corrected_code:
const patientSubscriptionResolvers = {
  Subscription: {
    patientVitalsAlert: {
      subscribe: withFilter(
        () => pubsub.asyncIterator(['VITALS_ALERT_CHANNEL']),
        async (payload, args, context) => {
          if (!context.currentUser || payload.patientId !== args.patientId) return false;
          const assigned = await CareTeamMember.findOne({
            where: { staffId: context.currentUser.id, patientId: args.patientId, active: true }
          });
          return !!assigned;
        }
      ),
      resolve: (payload) => payload.vitalSigns
    }
  }
};
